class Animal:
    def __init__(self, name):
        self.name = name


class Fish(Animal):
    def __init__(self, name, fat):
        super().__init__(name)
        self.fat = fat

    def speak(self):
        print(self.name + "：咕噜咕噜，本鱼有 " + str(self.fat) + " 斤")


name = input()
fat = int(input())
f = Fish(name, fat)
f.speak()
